import{z as o,x as d,o as E,c as B,q as i,j as l,D as t,d as e,s,S as A,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"奖励归一化与白化","description":"","frontmatter":{"title":"奖励归一化与白化","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/reward-whitening.md","filePath":"llm/reward-whitening.md","lastUpdated":1791413859000}'),p={name:"llm/reward-whitening.md"};function m(h,a,D,u,P,g){const n=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=i('<h1 id="奖励归一化与白化" tabindex="-1">奖励归一化与白化 <a class="header-anchor" href="#奖励归一化与白化" aria-label="Permalink to &quot;奖励归一化与白化&quot;">​</a></h1><div class="epigraph"><p>奖励的单位随 RM、校验器与长度漂移；不把尺度钉住，学习率与 clip 都在打移动靶。</p><footer>—— 对照 PPO 实现里的 advantage whitening；群体方法里的组内标准化；Dr. GRPO 对标准差项的批评</footer></div><p><a href="/llm/value-model-init">上一课</a>让 \\(V\\) 去拟合回报。回报的量纲若一步一变，\\(V\\) 永远在追尺度而不是追结构。缺口是：<strong>\\(r\\) 的零点与方差必须在进入 GAE / 组优势之前被定义。</strong> 本课写 running 统计、batch 白化、组内标准化，以及它们如何与 <a href="/llm/rm-calibration">校准</a>、<a href="/llm/multi-objective-reward">多目标加权</a> 打架。不重推 <a href="/llm/grpo">GRPO</a> 公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RM logit、通过率、\\(\\pm 1\\) 规则奖励、逐步 KL，量纲不同。PPO 的有效步长是 \\(\\eta\\times \\hat A\\)；\\(\\hat A\\) 随 \\(r\\) 的标准差线性变，等于隐式改学习率。训练过程中策略变好，\\(r\\) 的均值上升，若不减均值，正优势变成默认，clip 长期打在上侧。白化（减均值除标准差）把 \\(\\hat A\\) 钉在单位方差，学习率才有跨实验可比性。</p><p><span class="marginnote">数字实例：\\(\\hat A\\) 与 \\(r\\) 的标准差成正比。若训练中 \\(r\\) 的 std 从 \\(0.5\\) 涨到 \\(2\\)（策略样本分化变大），同一份梯度系数等于放大四倍——你没动学习率，却隐式调了四倍。白化把 std 钉回 \\(1\\)，配置里的学习率才真的是那个学习率。</span></p><p>GRPO 在<strong>组内</strong>做 \\((r-\\mathrm{mean})/\\mathrm{std}\\)，已经是一种白化，但按题，不是按全局。Dr. GRPO（Liu 等）指出：组内 std 把「这题本来分差就大」变成优势幅度，引入难度偏差。是否除 std，是本课要显式选择的开关。running 统计的半衰期也要写进配置：太短则一步一变，太长则跟不上策略。</p><h3 id="白化奖励还是白化优势" tabindex="-1">白化奖励还是白化优势 <a class="header-anchor" href="#白化奖励还是白化优势" aria-label="Permalink to &quot;白化奖励还是白化优势&quot;">​</a></h3><p>对 \\(r\\) 做 running 标准化，再送 GAE，价值目标的量纲稳定。只对 \\(\\hat A\\) 做 batch 白化，不改变 \\(V\\) 要回归的尺度，但稳定策略梯度。两层都做，等于除了两次方差，更新过弱。只做一次，写进配置。</p><p><span class="marginnote">校准是仿射对齐胜率；白化是训练稳定性。先校准再白化，胜率含义被再次丢掉——在线 PPO 通常只白化，把校准留给阈值与评测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>运行均值 / 方差：对序列 \\(R\\) 用指数滑动，再 \\(R&#39;=(R-\\mu)/(\\sigma+\\varepsilon)\\)。Batch 内优势白化：当前 minibatch 上对 \\(\\hat A\\) 减均除标。组内：仅对同一 \\(x\\) 的 \\(G\\) 条。DAPO 用规则 \\(\\pm 1\\) 再组内标准化，不再做全局 running。可验证域若已是 \\(\\pm 1\\)，全局白化几乎只减均值。</p>',12)),(E(),l(A,null,{default:t(()=>[s(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%8E%9F%E5%A7%8B%20r%20%2F%20R%22%5D%20--%3E%20CH%5B%22%E9%80%89%E4%B8%80%E5%B1%82%EF%BC%9Arunning%20%2F%20batch%20%2F%20%E7%BB%84%E5%86%85%22%5D%0A%20%20CH%20--%3E%20A%5B%22A%CC%82%20%E8%BF%9B%E5%85%A5%20clip%22%5D%0A%20%20CH%20--%3E%20DUP%5B%22%E7%A6%81%E6%AD%A2%E6%9C%AA%E5%A3%B0%E6%98%8E%E7%9A%84%E5%8F%8C%E9%87%8D%E9%99%A4%E6%96%B9%E5%B7%AE%22%5D%0A%20%20STD%5B%22%E6%98%AF%E5%90%A6%E9%99%A4%20std%22%5D%20--%3E%20BIAS%5B%22%E7%BB%84%E5%86%85%20std%20%E5%BC%95%E5%85%A5%E9%9A%BE%E5%BA%A6%E5%81%8F%E5%B7%AE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"多目标：必须在加权之后或之前锁一种（上一课）。加权前各自白化，则 \\(w\\) 近似重要性；加权后再白化，\\(w\\) 只影响合成方向，整体尺度被钉死。",-1)),a[4]||(a[4]=r("p",null,[r("span",{class:"marginnote"},"常见误区：初学者容易把白化当无害的预处理，到处补一层。多目标里加权前各自白化等于宣布「每个目标重要性相同」，权重 \\(w\\) 被架空；两层都除方差又把更新压得过弱。白化是一次性的尺度决策，不是免费稳定剂。")],-1)),a[5]||(a[5]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=r("p",null,"减均值去掉「人人有奖」的偏置，使相对好坏成为梯度。除标准差使难题（\\(r\\) 分布宽）与易题（分布窄）的更新幅度同量级——这可能是优点（都学一点）或缺点（难题不该与易题同幅度，Dr. GRPO 的论点）。不除 std、只减均值，保留原始分差，学习率要随奖励定义重扫。",-1)),(E(),l(A,null,{default:t(()=>[s(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%8E%9F%E5%A7%8B%E5%A5%96%E5%8A%B1%20r%22%5D%20--%3E%20M%5B%22%E5%8F%AA%E5%87%8F%E5%9D%87%E5%80%BC%22%5D%0A%20%20R%20--%3E%20MS%5B%22%E5%87%8F%E5%9D%87%E5%80%BC%E5%86%8D%E9%99%A4%20std%22%5D%0A%20%20M%20--%3E%20M1%5B%22%E5%8E%BB%E6%8E%89%E4%BA%BA%E4%BA%BA%E6%9C%89%E5%A5%96%E7%9A%84%E5%81%8F%E7%BD%AE%22%5D%0A%20%20M%20--%3E%20M2%5B%22%E4%BF%9D%E7%95%99%E5%8E%9F%E5%A7%8B%E5%88%86%E5%B7%AE%EF%BC%9A%E9%9A%BE%E9%A2%98%E6%AD%A5%E5%B9%85%E5%A4%A7%22%5D%0A%20%20MS%20--%3E%20S1%5B%22%E4%BC%98%E5%8A%BF%E9%92%89%E5%9C%A8%E5%8D%95%E4%BD%8D%E6%96%B9%E5%B7%AE%22%5D%0A%20%20MS%20--%3E%20S2%5B%22%E9%9A%BE%E9%A2%98%E4%B8%8E%E6%98%93%E9%A2%98%E5%90%8C%E5%B9%85%E5%BA%A6%EF%BC%9A%E9%9A%BE%E5%BA%A6%E5%81%8F%E5%B7%AE%22%5D%0A%20%20S2%20--%3E%20DG%5B%22Dr.%20GRPO%EF%BC%9A%E7%BB%84%E5%86%85%E4%B8%8D%E9%99%A4%20std%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">为什么重要：过优化监控要画「代理减金标」的差，两边必须用原始尺度。若各自白化后再画，差值的意义被改写，拐点可能整段消失或凭空出现——监控图表的量纲必须与训练里用的量纲是同一套。</span></p><p><span class="marginnote">\\(\\varepsilon\\) 要够大。全对组 \\(\\sigma\\to 0\\) 会炸；DAPO 选择直接丢掉该组，而不是除一个假的 \\(\\sigma\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p><a href="/llm/rm-overoptimization">过优化</a> 监控的金标不要白化后再和代理画同一张图，否则拐点被尺度藏住。异步 off-policy 下 running 统计混了多版本策略，均值滞后，早期过估计。白化层数、是否除 std、滑动半衰期必须写进实验卡，换奖励定义后学习率要重扫。下一课专门处理长度进入分母或进入 \\(r\\) 时的系统偏差，它常被误写成「再白化一次」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>白化钉住优势尺度，使学习率与 clip 跨实验可比。</li><li>只做一层：running \\(r\\)、batch \\(\\hat A\\)、或组内；禁止悄悄除两次。</li><li>组内除 std 会混入难度偏差，是可关开关。</li><li>校准与白化目的不同，在线 PPO 通常只白化。</li><li>出处：PPO 实现惯例；Shao 等 GRPO 组内标准化；Liu 等 Dr. GRPO；Yu 等 DAPO 对零方差组的处理。</li></ul>',6))])}const b=o(p,[["render",m]]);export{f as __pageData,b as default};
